-- DevStaging only. All profile changes and generated notifications roll back.
begin;
create temp table profile_test_results(label text,passed boolean);
grant select,insert on profile_test_results to authenticated,anon;
create function pg_temp.check_test(label text,value boolean) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'FAILED: %',label; end if; insert into profile_test_results values(label,true); end; $$;
create function pg_temp.deny(label text,statement text,state text default '42501') returns void language plpgsql as $$ declare denied boolean:=false; begin begin execute statement; exception when others then if sqlstate<>state then raise exception 'FAILED: %, expected %, got %',label,state,sqlstate; end if; denied:=true; end; perform pg_temp.check_test(label,denied); end; $$;
create function pg_temp.actor(id uuid) returns void language plpgsql as $$ begin perform set_config('request.jwt.claim.sub',coalesce(id::text,''),true); perform set_config('request.jwt.claims',case when id is null then '{}' else json_build_object('sub',id,'role','authenticated')::text end,true); end; $$;
do $$ declare fixture record; youth_b uuid; company_b uuid; begin
select j.id as job,j.company_user_id as company,y.user_id as youth,y.recruitment_profile_version as version into fixture from public.swipe_actions s join public.jobs j on j.id=s.job_id join public.company_profiles cp on cp.user_id=j.company_user_id join public.youth_profiles y on y.user_id=s.youth_user_id where s.decision='interested' and cp.verification_status='verified' and not public.users_are_blocked(cp.user_id,y.user_id) limit 1;
if fixture.job is null then raise exception 'Missing DEV fixture'; end if;
select user_id into youth_b from public.youth_profiles where user_id<>fixture.youth limit 1;
select user_id into company_b from public.company_profiles where user_id<>fixture.company and verification_status='verified' limit 1;
if youth_b is null or company_b is null then raise exception 'Missing DEV isolation actors'; end if;
perform set_config('mnw.profile_fixture',jsonb_build_object('job',fixture.job,'company',fixture.company,'youth',fixture.youth,'version',fixture.version,'youth_b',youth_b,'company_b',company_b)::text,true);
end; $$;
create function pg_temp.fixture(key text) returns text language sql as $$ select current_setting('mnw.profile_fixture')::jsonb->>key; $$;
select pg_temp.check_test('default optional profile is valid',public.valid_recruitment_profile((select recruitment_profile from public.youth_profiles where user_id=pg_temp.fixture('youth')::uuid)));
select pg_temp.check_test('unknown section denied',not public.valid_recruitment_profile('{"verified":true}'));
set local role anon;
select pg_temp.actor(null);
select pg_temp.deny('anonymous cannot save optional profile','select public.save_my_recruitment_profile(''examples'',''[]'',0)');
select pg_temp.deny('anonymous cannot read candidate input','select public.get_candidate_assessment_input('||quote_literal(pg_temp.fixture('job'))||'::uuid,'||quote_literal(pg_temp.fixture('youth'))||'::uuid)');
set local role authenticated;
select pg_temp.actor(pg_temp.fixture('youth')::uuid);
select public.save_my_recruitment_profile('availability','{"days":["sat","sun"],"periods":["evening"],"startDate":"2026-11-01","hours":"12"}',pg_temp.fixture('version')::integer);
select pg_temp.check_test('own save succeeds',(select recruitment_profile->'availability'->>'hours'='12' from public.youth_profiles where user_id=pg_temp.fixture('youth')::uuid));
select pg_temp.check_test('version increments',(select recruitment_profile_version=(pg_temp.fixture('version')::integer+1) from public.youth_profiles where user_id=pg_temp.fixture('youth')::uuid));
select pg_temp.deny('stale save denied','select public.save_my_recruitment_profile(''examples'',''[]'','||pg_temp.fixture('version')||')','40001');
select pg_temp.deny('invalid period denied','select public.save_my_recruitment_profile(''availability'',''{"days":[],"periods":["anything"],"startDate":"","hours":""}'','||(pg_temp.fixture('version')::integer+1)||')','22023');
select pg_temp.deny('invalid date denied','select public.save_my_recruitment_profile(''availability'',''{"days":[],"periods":[],"startDate":"2026-02-30","hours":""}'','||(pg_temp.fixture('version')::integer+1)||')','22023');
select pg_temp.deny('extra verified flag denied','select public.save_my_recruitment_profile(''examples'',''[{"strength":"service","context":"Test","action":"Own example","verified":true}]'','||(pg_temp.fixture('version')::integer+1)||')','22023');
select pg_temp.check_test('calendar validation independent of claims',not public.valid_recruitment_profile(jsonb_set((select recruitment_profile from public.youth_profiles where user_id=pg_temp.fixture('youth')::uuid),'{availability,startDate}','"2026-02-30"')));
select public.save_my_recruitment_profile('examples','[{"strength":"service","context":"Synthetic kiosk","action":"I helped synthetic customers."}]',(pg_temp.fixture('version')::integer+1));
select pg_temp.check_test('section save preserves other sections',(select recruitment_profile->'availability'->>'hours'='12' from public.youth_profiles where user_id=pg_temp.fixture('youth')::uuid));
select pg_temp.actor(pg_temp.fixture('youth_b')::uuid);
select pg_temp.check_test('another youth cannot read profile',(select count(*)=0 from public.youth_profiles where user_id=pg_temp.fixture('youth')::uuid));
select pg_temp.deny('another youth cannot read candidate input','select public.get_candidate_assessment_input('||quote_literal(pg_temp.fixture('job'))||'::uuid,'||quote_literal(pg_temp.fixture('youth'))||'::uuid)');
select pg_temp.actor(pg_temp.fixture('company_b')::uuid);
select pg_temp.deny('unrelated verified company denied','select public.get_candidate_assessment_input('||quote_literal(pg_temp.fixture('job'))||'::uuid,'||quote_literal(pg_temp.fixture('youth'))||'::uuid)');
select pg_temp.actor(pg_temp.fixture('company')::uuid);
select pg_temp.deny('company cannot save youth profile','select public.save_my_recruitment_profile(''examples'',''[]'',0)');
select pg_temp.check_test('listing owner reads submitted optional profile',public.get_candidate_assessment_input(pg_temp.fixture('job')::uuid,pg_temp.fixture('youth')::uuid)->'recruitment_profile'->'examples'->0->>'context'='Synthetic kiosk');
reset role;
insert into public.user_blocks(blocker_user_id,blocked_user_id) values(pg_temp.fixture('youth')::uuid,pg_temp.fixture('company')::uuid) on conflict do nothing;
set local role authenticated;
select pg_temp.actor(pg_temp.fixture('company')::uuid);
select pg_temp.deny('blocking removes optional profile access','select public.get_candidate_assessment_input('||quote_literal(pg_temp.fixture('job'))||'::uuid,'||quote_literal(pg_temp.fixture('youth'))||'::uuid)');
reset role;
select jsonb_build_object('passed',count(*),'tests',jsonb_agg(label)) from profile_test_results;
rollback;
